{"source":"#include<stdio.h>

int main(int argc, char *argv[])
{
int n,i,j;
scanf("%d",&n);

if(n==1)
    { printf("1 0\n"); return 0; }

int arr[n];

for(i=0;i<n;i++)
scanf("%d",&arr[i]);

int cna=0,cnb=0;
int t1=0,t2=0;

i=0;
j=n-1;

cna++; cnb++;
t1+=arr[0];
t2+=arr[n-1];

while(i<j)
{
    if(t1<t2)
    {
        i++;
        cna++;
        t1+=arr[i];
    }
    else if(t2<t1)
    {
        j--;
        cnb++;
        t2+=arr[j];
    }
    else
    {
        if(i+1==j)
            break;
        j--;
        cnb++;
        t2+=arr[j];

        i++;
        cna++;
        t1+=arr[i];
    }
}

printf("%d %d\n",cna,cnb);


return 0;
}"}
